//! TLS identity management for the Kosh server.
//!
//! This module handles the full lifecycle of the server's self-signed TLS certificate:
//!
//! - **Generation** — on first boot, a self-signed X.509 certificate is generated by
//!   [`rcgen`] and written to `<vault_path>/tls/`. In addition to standard loopback SANs
//!   (`localhost`, `127.0.0.1`, `0.0.0.0`), the certificate automatically includes all
//!   detected local LAN IP addresses (via [`lan_ips`]) and the mDNS local domain
//!   (`<hostname>.local`) when mDNS discovery is enabled.
//! - **Loading** — on subsequent boots, the existing `cert.pem` and `key.pem` files are
//!   read back from disk.
//! - **Fingerprinting** — the SHA-256 fingerprint of the certificate's DER encoding is
//!   made available in two forms:
//!   - A hex string for display purposes.
//!   - A raw `[u8; 32]` for use by the admin CLI to derive the BIP-39 verification
//!     mnemonic and to encode the pairing QR code.
//!
//! The certificate is used both by the Axum HTTP server (via `axum_server` / `rustls`)
//! and by client applications (such as the Kosh Android app), which pin the certificate
//! fingerprint on first connection (Trust-On-First-Use / TOFU).

mod cert;
mod error;

pub use cert::Identity;
pub use cert::lan_ips;
pub use error::{Error, Result};

use crate::config::Config;
use crate::tls;

#[cfg(test)]
mod test;

/// Initializes the TLS identity by loading existing certificates or generating fresh ones with LAN and mDNS SANs.
///
/// Discovers all local, non-loopback network interface IP addresses via [`lan_ips`].
/// If mDNS discovery is enabled in [`Config::mdns`], appends `<hostname>.local` to the
/// list of Subject Alternative Names. Then either loads existing PEM credentials from
/// `<vault_path>/tls/` or forges a new self-signed certificate covering all gathered SANs.
///
/// # Arguments
///
/// * `config` - The loaded server configuration containing `vault_path` and `mdns` settings.
///
/// # Errors
///
/// - Returns [`Error::Io`] if the `<vault_path>/tls/` directory cannot be created or PEM files cannot be read/written.
/// - Returns [`Error::CertificateGen`] if generating the self-signed X.509 certificate fails.
pub async fn init(config: &Config) -> Result<Identity> {
    let mut extra_sans = tls::lan_ips();
    if config.mdns.enable {
        extra_sans.push(format!("{}.local", config.mdns.hostname));
    }

    let identity =
        Identity::load_or_create(&config.vault_path, &extra_sans).await?;
    Ok(identity)
}
